export function buildConsistentSnapshot(signals=[], {targetAt=Date.now(),maxSkewMs=600000,required=[]}={}){const by=new Map(signals.map(x=>[x.key,x]));const missing=required.filter(k=>!by.has(k));if(missing.length)return {ok:false,reason:'MISSING_REQUIRED',missing};const selected=[];let min=Infinity,max=-Infinity;for(const s of signals){const t=Number(new Date(s.observedAt??s.validAt??0));if(!Number.isFinite(t))continue;if(Math.abs(t-targetAt)>maxSkewMs)continue;selected.push(s);min=Math.min(min,t);max=Math.max(max,t)}if(required.some(k=>!selected.some(s=>s.key===k)))return {ok:false,reason:'OUTSIDE_TIME_WINDOW'};if(selected.length&&max-min>maxSkewMs)return {ok:false,reason:'CROSS_SIGNAL_SKEW'};return {ok:true,signals:selected,skewMs:selected.length?max-min:0,targetAt:new Date(targetAt).toISOString()}}
